/**
 * Public surface of the order lifecycle.
 */
export { COMMAND_TYPES, STATES, TERMINAL_STATES, allowedTypes, isTerminal } from './machine.js';
export { Order } from './order.js';
---
/**
 * The order state machine: the vocabulary of states and commands, and which
 * commands each state accepts.
 */

/** Every state an order can occupy, in lifecycle order. */
export const STATES = Object.freeze([
  'created',
  'paid',
  'packed',
  'shipped',
  'delivered',
  'cancelled',
  'refunded',
]);

/** Every command an order accepts. */
export const COMMAND_TYPES = Object.freeze([
  'addItem',
  'removeItem',
  'pay',
  'pack',
  'ship',
  'deliver',
  'cancel',
  'refund',
]);

/** States that accept no further command. */
export const TERMINAL_STATES = Object.freeze(['cancelled', 'refunded']);

/**
 * Commands a state accepts.
 *
 * @param {string} state State to look up.
 * @returns {string[]} Allowed command types in ascending order.
 */
export function allowedTypes(state) {
  throw new Error('not implemented');
}

/**
 * Report whether a state accepts no further command.
 *
 * @param {string} state State to look up.
 * @returns {boolean} True for a terminal state.
 */
export function isTerminal(state) {
  throw new Error('not implemented');
}
---
/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 *
 * Construction and the read side exist; nothing applies commands yet.
 */

/** An order and everything that has been asked of it. */
export class Order {
  #id;

  #state = 'created';

  #items = new Map();

  #paidCents = 0;

  #refundedCents = 0;

  #clockMs;

  #audit = [];

  #shipment = null;

  #deliveredAt = null;

  /**
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   */
  constructor(init) {
    if (typeof init !== 'object' || init === null) throw new TypeError('init must be an object');
    if (typeof init.id !== 'string' || init.id === '') throw new TypeError('init.id must be a non-empty string');
    const createdAt = init.createdAt === undefined ? 0 : init.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0) {
      throw new TypeError('init.createdAt must be a non-negative integer');
    }
    this.#id = init.id;
    this.#clockMs = createdAt;
  }

  /** @returns {string} Order identity. */
  get id() {
    return this.#id;
  }

  /** @returns {string} Current state. */
  get state() {
    return this.#state;
  }

  /** @returns {Array<{sku: string, qty: number, unitPriceCents: number}>} Items in ascending sku order. */
  get items() {
    return [...this.#items.keys()].sort().map((sku) => ({ ...this.#items.get(sku) }));
  }

  /** @returns {number} Sum of quantity times unit price over all items. */
  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    throw new Error('not implemented');
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    throw new Error('not implemented');
  }
}
---
{
  "name": "order-lifecycle",
  "type": "module",
  "private": true,
  "scripts": {
    "test": "node --test test/*.test.js"
  }
}
---
{
  "id": "code:order-lifecycle",
  "tier": 3,
  "domain": "state-machines",
  "title": "Order state machine with an audit trail and idempotent commands",
  "prompt": "Finish the order aggregate in `src/`. `src/index.js` re-exports `STATES`, `COMMAND_TYPES`, `TERMINAL_STATES`, `allowedTypes` and `isTerminal` from `src/machine.js` and `Order` from `src/order.js`; keep that surface. The states are `created`, `paid`, `packed`, `shipped`, `delivered`, `cancelled` and `refunded`; the commands are `addItem`, `removeItem`, `pay`, `pack`, `ship`, `deliver`, `cancel` and `refund`. `created` accepts `addItem`, `removeItem`, `pay` and `cancel`; `paid` accepts `pack` and `cancel`; `packed` accepts `ship` and `cancel`; `shipped` accepts `deliver`; `delivered` accepts `refund`; `cancelled` and `refunded` accept nothing and are the terminal states. `allowedTypes(state)` returns that state's commands in ascending order as a fresh array a caller may mutate, and `isTerminal(state)` reports whether the list is empty; both throw `TypeError` with message `unknown state: <state>` for anything else. The exported lists are frozen.\n\n`new Order({ id, createdAt })` starts an order in `created` with no items, nothing paid and nothing refunded. `id` must be a non-empty string and `createdAt`, which defaults to 0, a non-negative integer; violations throw `TypeError` with messages `init must be an object`, `init.id must be a non-empty string` and `init.createdAt must be a non-negative integer`. The read side exposes `id`, `state`, `items` (ascending by sku), `totalCents` (the sum of quantity times unit price), `paidCents`, `refundedCents`, `clockMs`, `shipment`, `deliveredAt`, the `audit` trail and `snapshot()`, which returns `{ id, state, items, totalCents, paidCents, refundedCents, clockMs, seq }` with `seq` the number of audit entries. Every one of these hands back copies: mutating what a getter returned must not change the order.\n\n`apply(command)` runs one command and returns a plain result instead of throwing for business failures. A command carries a `type`, a non-empty `commandId`, a non-negative integer `at`, and the fields its type needs. A structurally malformed command throws `TypeError` and is not recorded: `command must be an object`, `unknown command type: <type>`, `command must carry a non-empty commandId`, `command must carry a non-negative integer at`. Otherwise the checks run in this order, and the first failure decides the outcome. A `commandId` that has been applied before returns exactly the result recorded for it, with `replayed` set to true, and changes nothing at all. An `at` earlier than `clockMs` is rejected with code `'CLOCK_REGRESSION'`, and its audit entry is stamped with the order's current clock so recorded times never decrease; every other command sets `clockMs` to its `at`. A command the current state does not allow is rejected with `'BAD_STATE'`. Then the command's own fields are checked: a missing or empty `sku`, `carrier`, `tracking` or `reason` gives `'MISSING_FIELD'`, and a `qty`, `unitPriceCents` or `amountCents` that is not an integer in range gives `'BAD_AMOUNT'` (`qty` and a refund `amountCents` must be at least 1; `unitPriceCents` and a payment `amountCents` must be at least 0). Then the business guards: adding a sku that is already present gives `'DUPLICATE_SKU'`, removing one that is not gives `'NO_SUCH_ITEM'`, paying an order with no items gives `'EMPTY_ORDER'`, paying anything other than `totalCents` gives `'AMOUNT_MISMATCH'`, and refunding more than `paidCents - refundedCents` gives `'REFUND_TOO_LARGE'`. A successful result is `{ ok: true, state, seq, replayed }` and a rejection is `{ ok: false, code, message, state, seq, replayed }`, where `message` is a non-empty explanation and `seq` is the audit entry number.\n\nEvery command that gets as far as the clock check appends exactly one audit entry, whether it succeeded or not: `{ seq, commandId, type, at, from, to, ok }` plus `code` on a rejection, with `seq` counting from 1, `from` the state before and `to` the state after, so a rejection has `from` equal to `to`. Effects: `addItem` and `removeItem` edit the item list and leave the state at `created`; `pay` records `amountCents` as `paidCents` and moves to `paid`; `pack` moves to `packed`; `ship` records the carrier and tracking and moves to `shipped`; `deliver` records `at` as `deliveredAt` and moves to `delivered`; `cancel` refunds everything captured so far and moves to `cancelled`; `refund` adds to `refundedCents` and moves to `refunded` only once the whole payment has been returned. `refundedCents` never exceeds `paidCents`. The static `Order.replay(init, commands)` builds a fresh order and applies each command in turn, giving the same snapshot and audit trail as applying them one at a time; a non-array argument throws `TypeError`.",
  "heldOut": false,
  "immutable": ["test", "package.json"],
  "checks": [
    { "id": "tests-pass", "outcome": "the test suite passes", "run": "node --test test/*.test.js" },
    { "id": "no-dependencies", "outcome": "no packages were installed", "run": "test ! -e node_modules" }
  ]
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { COMMAND_TYPES, STATES, TERMINAL_STATES, allowedTypes, isTerminal } from '../src/index.js';

test('the vocabulary is fixed and frozen', () => {
  assert.deepEqual([...STATES], ['created', 'paid', 'packed', 'shipped', 'delivered', 'cancelled', 'refunded']);
  assert.deepEqual([...COMMAND_TYPES].sort(), [
    'addItem',
    'cancel',
    'deliver',
    'pack',
    'pay',
    'refund',
    'removeItem',
    'ship',
  ]);
  assert.deepEqual([...TERMINAL_STATES].sort(), ['cancelled', 'refunded']);
  assert.equal(Object.isFrozen(STATES), true);
  assert.equal(Object.isFrozen(COMMAND_TYPES), true);
  assert.equal(Object.isFrozen(TERMINAL_STATES), true);
});

test('each state accepts exactly the documented commands', () => {
  const table = {
    created: ['addItem', 'cancel', 'pay', 'removeItem'],
    paid: ['cancel', 'pack'],
    packed: ['cancel', 'ship'],
    shipped: ['deliver'],
    delivered: ['refund'],
    cancelled: [],
    refunded: [],
  };
  for (const [state, expected] of Object.entries(table)) {
    assert.deepEqual(allowedTypes(state), expected, `allowedTypes(${state})`);
  }
  for (const state of STATES) {
    for (const type of allowedTypes(state)) {
      assert.ok(COMMAND_TYPES.includes(type), `${type} is a known command`);
    }
  }
  assert.throws(() => allowedTypes('shipping'), { name: 'TypeError', message: 'unknown state: shipping' });
});

test('terminal states are exactly those with no commands', () => {
  for (const state of STATES) {
    assert.equal(isTerminal(state), allowedTypes(state).length === 0, `isTerminal(${state})`);
    assert.equal(isTerminal(state), TERMINAL_STATES.includes(state), `${state} agrees with the list`);
  }
  assert.throws(() => isTerminal('nope'), { name: 'TypeError' });
});

test('mutating the exported lists cannot change the machine', () => {
  assert.throws(() => {
    STATES.push('archived');
  });
  assert.equal(STATES.length, 7);
  const copy = allowedTypes('created');
  copy.push('deliver');
  assert.deepEqual(allowedTypes('created'), ['addItem', 'cancel', 'pay', 'removeItem']);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { COMMAND_TYPES, Order, STATES, allowedTypes, isTerminal } from '../src/index.js';

/** Deterministic 32-bit PRNG so generated command sequences replay identically. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Build the happy-path order used by several cases. */
function deliveredOrder() {
  const order = new Order({ id: 'o-1', createdAt: 100 });
  order.apply({ type: 'addItem', commandId: 'c1', at: 100, sku: 'apple', qty: 2, unitPriceCents: 150 });
  order.apply({ type: 'addItem', commandId: 'c2', at: 101, sku: 'pear', qty: 1, unitPriceCents: 300 });
  order.apply({ type: 'pay', commandId: 'c3', at: 102, amountCents: 600 });
  order.apply({ type: 'pack', commandId: 'c4', at: 103 });
  order.apply({ type: 'ship', commandId: 'c5', at: 104, carrier: 'ups', tracking: 'zz9' });
  order.apply({ type: 'deliver', commandId: 'c6', at: 105 });
  return order;
}

test('construction validates its identity and clock', () => {
  assert.throws(() => new Order(null), { name: 'TypeError', message: 'init must be an object' });
  assert.throws(() => new Order({ id: '' }), { name: 'TypeError', message: 'init.id must be a non-empty string' });
  assert.throws(() => new Order({ id: 'o', createdAt: -1 }), { name: 'TypeError' });
  assert.throws(() => new Order({ id: 'o', createdAt: 1.5 }), { name: 'TypeError' });
  const order = new Order({ id: 'o' });
  assert.equal(order.id, 'o');
  assert.equal(order.state, 'created');
  assert.equal(order.clockMs, 0);
  assert.deepEqual(order.snapshot(), {
    id: 'o',
    state: 'created',
    items: [],
    totalCents: 0,
    paidCents: 0,
    refundedCents: 0,
    clockMs: 0,
    seq: 0,
  });
});

test('malformed commands throw instead of being recorded', () => {
  const order = new Order({ id: 'o' });
  assert.throws(() => order.apply(null), { name: 'TypeError', message: 'command must be an object' });
  assert.throws(() => order.apply({ type: 'fly', commandId: 'c', at: 1 }), {
    name: 'TypeError',
    message: 'unknown command type: fly',
  });
  assert.throws(() => order.apply({ type: 'pack', at: 1 }), {
    name: 'TypeError',
    message: 'command must carry a non-empty commandId',
  });
  assert.throws(() => order.apply({ type: 'pack', commandId: 'c', at: -1 }), { name: 'TypeError' });
  assert.throws(() => order.apply({ type: 'pack', commandId: 'c', at: 'now' }), { name: 'TypeError' });
  assert.equal(order.audit.length, 0);
});

test('the happy path walks the machine and records every step', () => {
  const order = deliveredOrder();
  assert.equal(order.state, 'delivered');
  assert.equal(order.totalCents, 600);
  assert.equal(order.paidCents, 600);
  assert.equal(order.refundedCents, 0);
  assert.equal(order.clockMs, 105);
  assert.deepEqual(order.items, [
    { sku: 'apple', qty: 2, unitPriceCents: 150 },
    { sku: 'pear', qty: 1, unitPriceCents: 300 },
  ]);
  assert.deepEqual(order.shipment, { carrier: 'ups', tracking: 'zz9' });
  assert.equal(order.deliveredAt, 105);
  const audit = order.audit;
  assert.equal(audit.length, 6);
  assert.deepEqual(audit.map((entry) => entry.seq), [1, 2, 3, 4, 5, 6]);
  assert.deepEqual(audit.map((entry) => entry.to), ['created', 'created', 'paid', 'packed', 'shipped', 'delivered']);
  assert.deepEqual(audit.map((entry) => entry.from), ['created', 'created', 'created', 'paid', 'packed', 'shipped']);
  assert.equal(audit.every((entry) => entry.ok === true), true);
  assert.equal(audit.every((entry) => !('code' in entry)), true);
});

test('the audit trail is a copy, not the live array', () => {
  const order = deliveredOrder();
  const audit = order.audit;
  audit.push({ seq: 99 });
  audit[0].type = 'tampered';
  assert.equal(order.audit.length, 6);
  assert.equal(order.audit[0].type, 'addItem');
  const items = order.items;
  items[0].qty = 99;
  assert.equal(order.items[0].qty, 2);
});

test('guards reject commands the state does not allow', () => {
  const order = new Order({ id: 'o' });
  const packed = order.apply({ type: 'pack', commandId: 'p', at: 1 });
  assert.equal(packed.ok, false);
  assert.equal(packed.code, 'BAD_STATE');
  assert.equal(packed.state, 'created');
  assert.equal(packed.seq, 1);
  assert.equal(packed.replayed, false);
  assert.equal(typeof packed.message, 'string');
  assert.ok(packed.message.length > 0);
  assert.deepEqual(order.audit[0], {
    seq: 1,
    commandId: 'p',
    type: 'pack',
    at: 1,
    from: 'created',
    to: 'created',
    ok: false,
    code: 'BAD_STATE',
  });
});

test('field and business guards use distinct codes', () => {
  const order = new Order({ id: 'o' });
  const cases = [
    [{ type: 'pay', commandId: 'a1', at: 1, amountCents: 0 }, 'EMPTY_ORDER'],
    [{ type: 'pay', commandId: 'a2', at: 1, amountCents: -5 }, 'BAD_AMOUNT'],
    [{ type: 'addItem', commandId: 'a3', at: 1, sku: '', qty: 1, unitPriceCents: 1 }, 'MISSING_FIELD'],
    [{ type: 'addItem', commandId: 'a4', at: 1, sku: 'x', qty: 0, unitPriceCents: 1 }, 'BAD_AMOUNT'],
    [{ type: 'addItem', commandId: 'a5', at: 1, sku: 'x', qty: 1.5, unitPriceCents: 1 }, 'BAD_AMOUNT'],
    [{ type: 'addItem', commandId: 'a6', at: 1, sku: 'x', qty: 1, unitPriceCents: -1 }, 'BAD_AMOUNT'],
    [{ type: 'removeItem', commandId: 'a7', at: 1, sku: 'ghost' }, 'NO_SUCH_ITEM'],
  ];
  for (const [command, code] of cases) {
    const result = order.apply(command);
    assert.equal(result.code, code, `${command.type} -> ${code}`);
  }
  assert.equal(order.apply({ type: 'addItem', commandId: 'b1', at: 2, sku: 'x', qty: 1, unitPriceCents: 250 }).ok, true);
  assert.equal(
    order.apply({ type: 'addItem', commandId: 'b2', at: 2, sku: 'x', qty: 3, unitPriceCents: 250 }).code,
    'DUPLICATE_SKU',
  );
  assert.equal(order.apply({ type: 'pay', commandId: 'b3', at: 3, amountCents: 249 }).code, 'AMOUNT_MISMATCH');
  assert.equal(order.apply({ type: 'pay', commandId: 'b4', at: 3, amountCents: 250 }).ok, true);
  assert.equal(order.state, 'paid');
  assert.equal(order.audit.length, 11);
});

test('shipping requires carrier and tracking', () => {
  const order = new Order({ id: 'o' });
  order.apply({ type: 'addItem', commandId: 'i', at: 1, sku: 'x', qty: 1, unitPriceCents: 100 });
  order.apply({ type: 'pay', commandId: 'p', at: 2, amountCents: 100 });
  order.apply({ type: 'pack', commandId: 'k', at: 3 });
  assert.equal(order.apply({ type: 'ship', commandId: 's1', at: 4, tracking: 't' }).code, 'MISSING_FIELD');
  assert.equal(order.apply({ type: 'ship', commandId: 's2', at: 4, carrier: 'c' }).code, 'MISSING_FIELD');
  assert.equal(order.state, 'packed');
  assert.equal(order.shipment, null);
  assert.equal(order.apply({ type: 'ship', commandId: 's3', at: 4, carrier: 'c', tracking: 't' }).ok, true);
  assert.equal(order.state, 'shipped');
});

test('refunds accumulate and close the order exactly once', () => {
  const order = deliveredOrder();
  assert.equal(order.apply({ type: 'refund', commandId: 'r0', at: 106, amountCents: 0 }).code, 'BAD_AMOUNT');
  assert.equal(order.apply({ type: 'refund', commandId: 'r1', at: 106, amountCents: 200 }).ok, true);
  assert.equal(order.state, 'delivered');
  assert.equal(order.refundedCents, 200);
  assert.equal(order.apply({ type: 'refund', commandId: 'r2', at: 107, amountCents: 401 }).code, 'REFUND_TOO_LARGE');
  assert.equal(order.apply({ type: 'refund', commandId: 'r3', at: 107, amountCents: 400 }).ok, true);
  assert.equal(order.state, 'refunded');
  assert.equal(order.refundedCents, order.paidCents);
  assert.equal(order.apply({ type: 'refund', commandId: 'r4', at: 108, amountCents: 1 }).code, 'BAD_STATE');
});

test('cancelling refunds whatever was captured', () => {
  const fresh = new Order({ id: 'o' });
  assert.equal(fresh.apply({ type: 'cancel', commandId: 'c', at: 1, reason: 'changed mind' }).ok, true);
  assert.equal(fresh.state, 'cancelled');
  assert.equal(fresh.refundedCents, 0);

  const paid = new Order({ id: 'o2' });
  paid.apply({ type: 'addItem', commandId: 'i', at: 1, sku: 'x', qty: 2, unitPriceCents: 700 });
  paid.apply({ type: 'pay', commandId: 'p', at: 2, amountCents: 1400 });
  assert.equal(paid.apply({ type: 'cancel', commandId: 'c1', at: 3, reason: '' }).code, 'MISSING_FIELD');
  assert.equal(paid.apply({ type: 'cancel', commandId: 'c2', at: 3, reason: 'out of stock' }).ok, true);
  assert.equal(paid.state, 'cancelled');
  assert.equal(paid.refundedCents, 1400);
  assert.equal(paid.paidCents, 1400);
});

test('a terminal order refuses every command', () => {
  const order = new Order({ id: 'o' });
  order.apply({ type: 'cancel', commandId: 'c', at: 1, reason: 'done' });
  assert.equal(isTerminal(order.state), true);
  const before = order.snapshot();
  let index = 0;
  for (const type of COMMAND_TYPES) {
    index += 1;
    const result = order.apply({
      type,
      commandId: `t${index}`,
      at: 2,
      sku: 'x',
      qty: 1,
      unitPriceCents: 1,
      amountCents: 1,
      carrier: 'c',
      tracking: 't',
      reason: 'r',
    });
    assert.equal(result.code, 'BAD_STATE', `${type} is refused`);
  }
  assert.equal(order.state, before.state);
  assert.equal(order.audit.length, 1 + COMMAND_TYPES.length);
});

test('a repeated command id replays its recorded outcome', () => {
  const order = new Order({ id: 'o' });
  const command = { type: 'addItem', commandId: 'once', at: 5, sku: 'x', qty: 1, unitPriceCents: 90 };
  const first = order.apply(command);
  assert.deepEqual(first, { ok: true, state: 'created', seq: 1, replayed: false });
  const again = order.apply({ ...command, at: 900, qty: 77 });
  assert.deepEqual(again, { ok: true, state: 'created', seq: 1, replayed: true });
  assert.equal(order.audit.length, 1);
  assert.equal(order.clockMs, 5);
  assert.deepEqual(order.items, [{ sku: 'x', qty: 1, unitPriceCents: 90 }]);

  const rejected = order.apply({ type: 'pack', commandId: 'nope', at: 6 });
  const rejectedAgain = order.apply({ type: 'pack', commandId: 'nope', at: 7 });
  assert.equal(rejected.replayed, false);
  assert.equal(rejectedAgain.replayed, true);
  assert.equal(rejectedAgain.code, 'BAD_STATE');
  assert.equal(rejectedAgain.seq, rejected.seq);
  assert.equal(order.audit.length, 2);
});

test('time never runs backwards', () => {
  const order = new Order({ id: 'o', createdAt: 100 });
  const late = order.apply({ type: 'addItem', commandId: 'x', at: 150, sku: 's', qty: 1, unitPriceCents: 5 });
  assert.equal(late.ok, true);
  assert.equal(order.clockMs, 150);
  const early = order.apply({ type: 'pack', commandId: 'y', at: 120 });
  assert.equal(early.code, 'CLOCK_REGRESSION');
  assert.equal(order.clockMs, 150);
  assert.equal(order.audit[1].at, 150, 'the entry is stamped with the order clock');
  const equal = order.apply({ type: 'removeItem', commandId: 'z', at: 150, sku: 's' });
  assert.equal(equal.ok, true, 'the same instant is allowed');
  assert.deepEqual(order.audit.map((entry) => entry.at), [150, 150, 150]);
});

test('replay reproduces a sequentially built order', () => {
  const commands = [
    { type: 'addItem', commandId: 'c1', at: 1, sku: 'b', qty: 1, unitPriceCents: 100 },
    { type: 'addItem', commandId: 'c2', at: 2, sku: 'a', qty: 2, unitPriceCents: 50 },
    { type: 'pack', commandId: 'c3', at: 3 },
    { type: 'pay', commandId: 'c4', at: 4, amountCents: 200 },
    { type: 'pack', commandId: 'c5', at: 5 },
  ];
  const stepwise = new Order({ id: 'o' });
  for (const command of commands) stepwise.apply(command);
  const replayed = Order.replay({ id: 'o' }, commands);
  assert.deepEqual(replayed.snapshot(), stepwise.snapshot());
  assert.deepEqual(replayed.audit, stepwise.audit);
  assert.equal(replayed.state, 'packed');
  assert.throws(() => Order.replay({ id: 'o' }, 'nope'), { name: 'TypeError' });
});

test('generated command sequences preserve every invariant', () => {
  const pick = mulberry32(86420);
  const skus = ['a', 'b', 'c'];
  for (let round = 0; round < 120; round += 1) {
    const commands = [];
    let clock = 0;
    for (let step = 0; step < 24; step += 1) {
      clock += pick() < 0.15 ? -3 : Math.floor(pick() * 4);
      const type = COMMAND_TYPES[Math.floor(pick() * COMMAND_TYPES.length)];
      commands.push({
        type,
        commandId: `r${round}s${step}`,
        at: Math.max(0, clock),
        sku: skus[Math.floor(pick() * skus.length)],
        qty: 1 + Math.floor(pick() * 3),
        unitPriceCents: Math.floor(pick() * 500),
        amountCents: Math.floor(pick() * 1500),
        carrier: pick() < 0.9 ? 'dhl' : '',
        tracking: 'trk',
        reason: 'because',
      });
    }
    const order = new Order({ id: `o${round}` });
    const results = commands.map((command) => order.apply(command));

    assert.ok(STATES.includes(order.state), 'state stays in the machine');
    assert.ok(order.refundedCents <= order.paidCents, 'refunds never exceed payments');
    assert.equal(
      order.totalCents,
      order.items.reduce((sum, item) => sum + item.qty * item.unitPriceCents, 0),
      'the total matches the items',
    );
    const audit = order.audit;
    assert.equal(audit.length, commands.length, 'every command leaves exactly one entry');
    audit.forEach((entry, index) => {
      assert.equal(entry.seq, index + 1, 'sequence numbers are contiguous');
      assert.equal(entry.from, index === 0 ? 'created' : audit[index - 1].to, 'states chain');
      assert.ok(index === 0 || entry.at >= audit[index - 1].at, 'time never goes backwards');
      assert.equal(entry.ok === false, 'code' in entry, 'only rejections carry a code');
      if (entry.ok) assert.ok(allowedTypes(entry.from).includes(entry.type), 'accepted commands were allowed');
    });
    assert.equal(results.filter((result) => result.replayed).length, 0, 'fresh ids are never replays');

    const snapshot = order.snapshot();
    const auditBefore = order.audit;
    for (const command of commands) {
      assert.equal(order.apply(command).replayed, true, 'a second pass replays');
    }
    assert.deepEqual(order.snapshot(), snapshot, 'a second pass changes nothing');
    assert.deepEqual(order.audit, auditBefore, 'a second pass records nothing');
    assert.deepEqual(Order.replay({ id: `o${round}` }, commands).snapshot(), snapshot, 'replay agrees');
  }
});

