{"file_path":"src/order.js","content":"/**
 * The order aggregate: guarded commands, an append-only audit trail and
 * idempotent replay of command ids.
 */

import { COMMAND_TYPES, allowedTypes } from './machine.js';

/** @returns {boolean} True for a non-empty string. */
function isNonEmptyString(value) {
  return typeof value === 'string' && value !== '';
}

/** @returns {boolean} True for an integer at least min. */
function isValidInt(value, min) {
  return typeof value === 'number' && Number.isInteger(value) && value >= min;
}

/** An order and everything that has been asked of it. */
export class Order {
  #id;

  #state = 'created';

  #items = new Map();

  #paidCents = 0;

  #refundedCents = 0;

  #clockMs;

  #audit = [];

  #shipment = null;

  #deliveredAt = null;

  #appliedCommands = new Map();

  /**
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   */
  constructor(init) {
    if (typeof init !== 'object' || init === null) throw new TypeError('init must be an object');
    if (typeof init.id !== 'string' || init.id === '') throw new TypeError('init.id must be a non-empty string');
    const createdAt = init.createdAt === undefined ? 0 : init.createdAt;
    if (!Number.isInteger(createdAt) || createdAt < 0) {
      throw new TypeError('init.createdAt must be a non-negative integer');
    }
    this.#id = init.id;
    this.#clockMs = createdAt;
  }

  /** @returns {string} Order identity. */
  get id() {
    return this.#id;
  }

  /** @returns {string} Current state. */
  get state() {
    return this.#state;
  }

  /** @returns {Array<{sku: string, qty: number, unitPriceCents: number}>} Items in ascending sku order. */
  get items() {
    return [...this.#items.keys()].sort().map((sku) => ({ ...this.#items.get(sku) }));
  }

  /** @returns {number} Sum of quantity times unit price over all items. */
  get totalCents() {
    let total = 0;
    for (const item of this.#items.values()) total += item.qty * item.unitPriceCents;
    return total;
  }

  /** @returns {number} Amount captured by a successful payment. */
  get paidCents() {
    return this.#paidCents;
  }

  /** @returns {number} Amount refunded so far. */
  get refundedCents() {
    return this.#refundedCents;
  }

  /** @returns {number} High-water mark of command timestamps. */
  get clockMs() {
    return this.#clockMs;
  }

  /** @returns {object[]} Copy of the audit trail, oldest first. */
  get audit() {
    return this.#audit.map((entry) => ({ ...entry }));
  }

  /** @returns {{carrier: string, tracking: string}|null} Shipment details once shipped. */
  get shipment() {
    return this.#shipment === null ? null : { ...this.#shipment };
  }

  /** @returns {number|null} Timestamp of delivery, once delivered. */
  get deliveredAt() {
    return this.#deliveredAt;
  }

  /** @returns {object} Plain description of the order's visible state. */
  snapshot() {
    return {
      id: this.#id,
      state: this.#state,
      items: this.items,
      totalCents: this.totalCents,
      paidCents: this.#paidCents,
      refundedCents: this.#refundedCents,
      clockMs: this.#clockMs,
      seq: this.#audit.length,
    };
  }

  /**
   * Apply one command.
   *
   * @param {object} command Command to apply.
   * @returns {{ok: boolean, state: string, seq: number, replayed: boolean, code?: string, message?: string}} Outcome.
   */
  apply(command) {
    if (typeof command !== 'object' || command === null) throw new TypeError('command must be an object');
    if (!COMMAND_TYPES.includes(command.type)) throw new TypeError(`unknown command type: ${command.type}`);
    if (typeof command.commandId !== 'string' || command.commandId === '') {
      throw new TypeError('command must carry a non-empty commandId');
    }
    if (!Number.isInteger(command.at) || command.at < 0) {
      throw new TypeError('command must carry a non-negative integer at');
    }

    if (this.#appliedCommands.has(command.commandId)) {
      return { ...this.#appliedCommands.get(command.commandId), replayed: true };
    }

    const from = this.#state;
    let at = command.at;
    let clockRegression = false;
    if (at < this.#clockMs) {
      clockRegression = true;
      at = this.#clockMs;
    } else {
      this.#clockMs = at;
    }

    const record = (ok, code, message) => {
      const seq = this.#audit.length + 1;
      const entry = { seq, commandId: command.commandId, type: command.type, at, from, to: this.#state, ok };
      if (!ok) entry.code = code;
      this.#audit.push(entry);
      const result = ok
        ? { ok: true, state: this.#state, seq, replayed: false }
        : { ok: false, code, message, state: this.#state, seq, replayed: false };
      this.#appliedCommands.set(command.commandId, result);
      return result;
    };

    if (clockRegression) {
      return record(false, 'CLOCK_REGRESSION', 'command arrives before the order clock');
    }

    if (!allowedTypes(from).includes(command.type)) {
      return record(false, 'BAD_STATE', `${command.type} is not allowed in state ${from}`);
    }

    switch (command.type) {
      case 'addItem': {
        if (!isNonEmptyString(command.sku)) return record(false, 'MISSING_FIELD', 'sku is required');
        if (!isValidInt(command.qty, 1)) return record(false, 'BAD_AMOUNT', 'qty must be an integer >= 1');
        if (!isValidInt(command.unitPriceCents, 0)) {
          return record(false, 'BAD_AMOUNT', 'unitPriceCents must be an integer >= 0');
        }
        if (this.#items.has(command.sku)) return record(false, 'DUPLICATE_SKU', `sku ${command.sku} already present`);
        this.#items.set(command.sku, { sku: command.sku, qty: command.qty, unitPriceCents: command.unitPriceCents });
        return record(true);
      }
      case 'removeItem': {
        if (!isNonEmptyString(command.sku)) return record(false, 'MISSING_FIELD', 'sku is required');
        if (!this.#items.has(command.sku)) return record(false, 'NO_SUCH_ITEM', `sku ${command.sku} not present`);
        this.#items.delete(command.sku);
        return record(true);
      }
      case 'pay': {
        if (!isValidInt(command.amountCents, 0)) {
          return record(false, 'BAD_AMOUNT', 'amountCents must be an integer >= 0');
        }
        if (this.#items.size === 0) return record(false, 'EMPTY_ORDER', 'cannot pay for an order with no items');
        if (command.amountCents !== this.totalCents) {
          return record(false, 'AMOUNT_MISMATCH', 'amountCents does not match the order total');
        }
        this.#paidCents = command.amountCents;
        this.#state = 'paid';
        return record(true);
      }
      case 'pack': {
        this.#state = 'packed';
        return record(true);
      }
      case 'ship': {
        if (!isNonEmptyString(command.carrier)) return record(false, 'MISSING_FIELD', 'carrier is required');
        if (!isNonEmptyString(command.tracking)) return record(false, 'MISSING_FIELD', 'tracking is required');
        this.#shipment = { carrier: command.carrier, tracking: command.tracking };
        this.#state = 'shipped';
        return record(true);
      }
      case 'deliver': {
        this.#deliveredAt = at;
        this.#state = 'delivered';
        return record(true);
      }
      case 'cancel': {
        if (!isNonEmptyString(command.reason)) return record(false, 'MISSING_FIELD', 'reason is required');
        this.#refundedCents = this.#paidCents;
        this.#state = 'cancelled';
        return record(true);
      }
      case 'refund': {
        if (!isValidInt(command.amountCents, 1)) {
          return record(false, 'BAD_AMOUNT', 'amountCents must be an integer >= 1');
        }
        if (command.amountCents > this.#paidCents - this.#refundedCents) {
          return record(false, 'REFUND_TOO_LARGE', 'amountCents exceeds the outstanding balance');
        }
        this.#refundedCents += command.amountCents;
        if (this.#refundedCents >= this.#paidCents) this.#state = 'refunded';
        return record(true);
      }
      default:
        throw new TypeError(`unknown command type: ${command.type}`);
    }
  }

  /**
   * Build an order by applying a command list in order.
   *
   * @param {{id: string, createdAt?: number}} init Identity and start time.
   * @param {object[]} commands Commands to apply.
   * @returns {Order} The resulting order.
   */
  static replay(init, commands) {
    if (!Array.isArray(commands)) throw new TypeError('commands must be an array');
    const order = new Order(init);
    for (const command of commands) order.apply(command);
    return order;
  }
}
"}

